def sumofFactors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            pair = n // i
            if pair != i and pair % 2 == 0:
                total += pair
        i += 1
    return total
```

